// Вся логика календаря в одном месте. На входе — строки листа «Календарь»
// и событие (сообщение / кнопка из Телеграма или еженедельный будильник).
// На выходе один пакет: какие строки записать в таблицу (upserts) и какие
// сообщения отправить/поправить (messages). Нейросети тут нет: разбор дат,
// склейка повторов и статусы — обычный код.
const OWNER = 285577543;
const MON_GEN = ['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
const MON_NOM = ['Январь','Февраль','Март','Апрель','Май','Июнь','Июль','Август','Сентябрь','Октябрь','Ноябрь','Декабрь'];
const MON_KEYS = [['янв','jan'],['фев','feb'],['мар','mar'],['апр','apr'],['мая','май','may'],['июн','jun'],['июл','jul'],['авг','aug'],['сен','sep'],['окт','oct'],['ноя','nov'],['дек','dec']];
const STATUS = { i: 'Идея', p: 'Выбран', w: 'В работе', d: 'Вышел', s: 'Отклонён' };
const MARK = { 'Идея': '', 'Выбран': ' ⭐', 'В работе': ' 🛠', 'Вышел': ' ✓', 'Отклонён': ' ✖' };
const CH = { pengui: '🔴 Pengui', tapestry: '🟡 Гобелены' };
const COLS = ['id','year','month','day','title','channel','status','project','note','sources','createdAt','updatedAt'];

const store = $getWorkflowStaticData('global');
store.pending = store.pending || {};
const nowIso = new Date().toISOString();
for (const k of Object.keys(store.pending)) {
  if (Date.now() - (store.pending[k].t || 0) > 3 * 86400000) delete store.pending[k];
}

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const chName = c => CH[c] || ('⚪ ' + c);
const srcList = r => String(r.sources || '').split(';').map(s => s.trim()).filter(Boolean);
const newId = () => 'o' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);

const rows = $('Читаем календарь').all().map(i => i.json)
  .filter(r => r && String(r.id || '').trim())
  .map(r => ({ ...r, id: String(r.id).trim(), month: Number(r.month), day: Number(r.day),
    year: r.year ? Number(r.year) : null, status: r.status || 'Идея', channel: r.channel || 'pengui' }));

const upserts = [];
const messages = [];
function toSheet(r) {
  const o = {};
  for (const c of COLS) o[c] = r[c] === null || r[c] === undefined ? '' : String(r[c]);
  return o;
}
function put(r) { r.updatedAt = nowIso; upserts.push(toSheet(r)); }

// ---------- даты ----------
const today = new Date(); today.setHours(0, 0, 0, 0);
function nextDate(r, from) {
  for (const y of [from.getFullYear(), from.getFullYear() + 1]) {
    if (r.year && r.year !== y) continue;
    const d = new Date(y, r.month - 1, r.day);
    if (d >= from) return d;
  }
  return null;
}
const short = d => d.getDate() + ' ' + MON_GEN[d.getMonth()].slice(0, 3);

// ---------- разбор списка ----------
function monthFromWord(w) { w = w.toLowerCase(); for (let i = 0; i < 12; i++) if (MON_KEYS[i].some(k => w.startsWith(k))) return i + 1; return 0; }
function parseLine(raw) {
  let line = raw.replace(/^[\s\-–—•*·>\d]*[.)]\s+/, '').replace(/^[\s\-–—•*·>]+/, '').replace(/\*\*/g, '').trim();
  if (!line) return null;
  let m, mo = 0, d = 0, y = null, matched = '';
  if ((m = line.match(/(\d{4})-(\d{1,2})-(\d{1,2})/))) { y = +m[1]; mo = +m[2]; d = +m[3]; matched = m[0]; }
  else if ((m = line.match(/(\d{1,2})(?:\s*[–-]\s*\d{1,2})?\s+([А-Яа-яЁёA-Za-z]{3,})\.?(?:\s+(\d{4}))?/)) && monthFromWord(m[2])) { d = +m[1]; mo = monthFromWord(m[2]); y = m[3] ? +m[3] : null; matched = m[0]; }
  else if ((m = line.match(/\b([A-Za-z]{3,})\.?\s+(\d{1,2})(?:st|nd|rd|th)?(?:,?\s+(\d{4}))?/)) && monthFromWord(m[1])) { mo = monthFromWord(m[1]); d = +m[2]; y = m[3] ? +m[3] : null; matched = m[0]; }
  else if ((m = line.match(/\b(\d{1,2})[./](\d{1,2})(?:[./](\d{2,4}))?\b/))) { d = +m[1]; mo = +m[2]; y = m[3] ? (m[3].length === 2 ? 2000 + +m[3] : +m[3]) : null; matched = m[0]; }
  let title = matched ? line.replace(matched, ' ') : line;
  title = title.replace(/^[\s\-–—:|,.()]+|[\s\-–—:|,(]+$/g, '').replace(/\s{2,}/g, ' ').trim();
  const ok = mo >= 1 && mo <= 12 && d >= 1 && d <= 31;
  return { title: title || line, rest: title, month: ok ? mo : 0, day: ok ? d : 0, year: y, ok, raw: line };
}
// Список целиком. Понимает и «дата — название — идея» в одну строку, и блоки:
// строка с датой, под ней название, под ним идея (как присылает ChatGPT).
// Строки-сноски («National Day Calendar», ссылки, «�») выбрасываются.
function isNoise(l) {
  return /^(national day calendar|days of the year|checkiday|wikipedia|timeanddate(\.com)?|источник|source)\s*:?\s*$/i.test(l) || /^https?:\/\//i.test(l);
}
const isDateOnlyTitle = s => /^[\d.\/\s–-]*$/.test(String(s || ''));
function parseList(text) {
  const items = [];
  let cur = null;
  const flush = () => { if (cur) { cur.ok = cur.ok && !!cur.title; items.push(cur); cur = null; } };
  for (let raw of String(text).split(/\n/)) {
    raw = raw.replace(/\uFFFD/g, '').trim();
    if (!raw || isNoise(raw)) continue;
    const p = parseLine(raw);
    if (!p) continue;
    if (p.ok) {
      flush();
      let title = p.rest || '', note = '';
      const sp = title.split(/\s+[—–]\s+/);
      if (sp.length > 1) { title = sp.shift().trim(); note = sp.join(' — ').trim(); }
      cur = { title, note, month: p.month, day: p.day, year: p.year, ok: true, raw: p.raw };
    } else if (cur && !cur.title) {
      cur.title = p.raw;
    } else if (cur) {
      cur.note = cur.note ? cur.note + '\n' + p.raw : p.raw;
    } else {
      items.push({ title: p.raw, note: '', month: 0, day: 0, year: null, ok: false, raw: p.raw });
    }
  }
  flush();
  return items;
}
const STOP = new Set(['день','дня','всемирный','всемирного','международный','международного','национальный','day','world','international','national','the','of','and','для','рождения','birthday','born']);
function words(s) { return new Set(String(s).toLowerCase().replace(/[^a-zа-яё0-9 ]/gi, ' ').split(/\s+/).filter(w => w.length > 2 && !STOP.has(w)).map(w => w.slice(0, 6))); }
function similar(a, b) { const A = words(a), B = words(b); if (!A.size || !B.size) return a.trim().toLowerCase() === b.trim().toLowerCase(); let k = 0; for (const w of A) if (B.has(w)) k++; return k / Math.min(A.size, B.size) >= 0.5; }
function classify(p) {
  // для текущего канала: новый / уже есть (какая строка) / повтор внутри списка / нет даты
  const ch = p.channel;
  const out = { fresh: [], dup: [], bad: [] };
  const batch = [];
  for (const it of p.lines) {
    if (!it.ok) { out.bad.push(it); continue; }
    const hit = rows.find(r => r.channel === ch && r.month === it.month && r.day === it.day && similar(r.title, it.title));
    if (hit) { out.dup.push({ it, hit }); continue; }
    const junk = rows.find(r => r.channel === ch && r.month === it.month && r.day === it.day && isDateOnlyTitle(r.title) && !out.fresh.some(f => f.repair === r));
    if (junk) { it.repair = junk; out.fresh.push(it); batch.push(it); continue; }
    if (batch.some(b => b.month === it.month && b.day === it.day && similar(b.title, it.title))) continue;
    batch.push(it); out.fresh.push(it);
  }
  return out;
}
const dstr = it => it.day + ' ' + MON_GEN[it.month - 1].slice(0, 3) + (it.year ? ' ' + it.year : '');
function previewText(p) {
  const c = classify(p);
  const L = [];
  L.push(`<b>Список поводов</b>: поводов ${p.lines.length}`);
  L.push(`🆕 новых: ${c.fresh.length}   🔁 уже есть: ${c.dup.length}${c.bad.length ? `   ⚠️ без даты: ${c.bad.length}` : ''}`);
  L.push(`Канал: <b>${esc(chName(p.channel))}</b>`);
  if (c.fresh.length) { L.push('', '<b>Новые</b>'); c.fresh.slice(0, 30).forEach(it => L.push(`• ${dstr(it)} — <b>${esc(it.title)}</b>${it.note ? '\n   <i>' + esc(it.note.slice(0, 90)) + (it.note.length > 90 ? '…' : '') + '</i>' : ''}`)); if (c.fresh.length > 30) L.push(`…и ещё ${c.fresh.length - 30}`); }
  if (c.dup.length) { L.push('', '<b>Уже в календаре</b> (станут ×' + '2+)'); c.dup.slice(0, 15).forEach(({ it, hit }) => L.push(`• ${dstr(it)} — ${esc(hit.title)} ×${srcList(hit).length + 1}`)); if (c.dup.length > 15) L.push(`…и ещё ${c.dup.length - 15}`); }
  if (c.bad.length) { L.push('', '<b>Не поняла дату</b>'); c.bad.slice(0, 10).forEach(it => L.push(`• ${esc((it.raw || it.title).slice(0, 80))}`)); }
  L.push('', 'Выбери канал и нажми «✅ Добавить».');
  return L.join('\n').slice(0, 4000);
}
function cardText(r) {
  const d = nextDate(r, today) || new Date(r.year || today.getFullYear(), r.month - 1, r.day);
  const n = srcList(r).length;
  const L = [`<b>${short(d)}</b> · ${esc(chName(r.channel))}`, `<b>${esc(r.title)}</b>${n > 1 ? ' ×' + n : ''}`, `Статус: <b>${esc(r.status)}</b>${MARK[r.status] || ''}`];
  if (r.project) L.push(`Проект: <code>${esc(r.project)}</code>`);
  if (r.note) L.push('', `<i>${esc(String(r.note).slice(0, 1500))}</i>`);
  if (n) L.push('', `Откуда: ${esc(srcList(r).join(', '))}`);
  L.push(`<code>id:${esc(r.id)}</code>`);
  return L.join('\n');
}
function summary(from, days, title) {
  const end = new Date(from); end.setDate(end.getDate() + days);
  const list = [];
  for (const r of rows) { if (r.status === 'Отклонён') continue; const d = nextDate(r, from); if (d && d <= end) list.push([d, r]); }
  list.sort((a, b) => a[0] - b[0]);
  if (!list.length) return `${title}\n\nПоводов нет.`;
  const L = [title, ''];
  let last = '';
  for (const [d, r] of list) {
    const k = short(d);
    const n = srcList(r).length;
    L.push(`${k === last ? '       ' : '<b>' + k + '</b>'} ${r.channel === 'tapestry' ? '🟡' : r.channel === 'pengui' ? '🔴' : '⚪'} ${esc(r.title)}${n > 1 ? ' ×' + n : ''}${MARK[r.status] || ''}`);
    last = k;
  }
  return L.join('\n').slice(0, 4000);
}
const HELP = [
  '<b>Studio Calendar</b>',
  '',
  '• Вставь список поводов от любой нейросети — одна строка, один повод. Даты: «20 января», «20.01», «January 20». Я покажу, что нового, а что уже есть.',
  '• <b>ближайшие</b> — поводы на 30 дней вперёд.',
  '• <b>октябрь</b> (или любой месяц) — поводы месяца списком.',
  '• Кнопка <b>«Календарь»</b> внизу слева — красивый календарь по месяцам: там выбираешь поводы и пишешь заметки.',
  '• <b>выбранные</b> — что ты выбрала на 3 месяца вперёд.',
  '• Ответь на карточку повода любым текстом — он добавится в заметки.',
  '',
  '⭐ выбран · 🛠 в работе · ✓ вышел · ×3 — предложили три источника.',
].join('\n');

// ---------- событие ----------
let tg = null;
if ($('Telegram Trigger').isExecuted) tg = $('Telegram Trigger').first().json;

if (!tg) {
  // еженедельный будильник
  const picked = rows.filter(r => ['Выбран', 'В работе'].includes(r.status));
  let text = summary(today, 14, '<b>Поводы на две недели</b>');
  if (!picked.length) text += '\n\nВыбранных пока нет — пришли «октябрь» или нужный месяц, чтобы выбрать.';
  messages.push({ type: 'send', chatId: OWNER, text });
} else if (tg.callback_query) {
  const cb = tg.callback_query;
  const chatId = cb.message.chat.id, messageId = cb.message.message_id, queryId = cb.id;
  const parts = String(cb.data || '').split('|');
  if (parts[0] === 'imp') {
    const p = store.pending[parts[1]];
    if (!p) {
      messages.push({ type: 'edit', chatId, messageId, text: 'Этот список уже обработан или устарел. Пришли его ещё раз.' });
      messages.push({ type: 'answer', queryId, text: 'Список устарел' });
    } else if (parts[2] === 'ch') {
      p.channel = parts[3];
      messages.push({ type: 'editImport', chatId, messageId, importId: parts[1], text: previewText(p) });
      messages.push({ type: 'answer', queryId, text: 'Канал: ' + chName(p.channel) });
    } else if (parts[2] === 'src') {
      p.source = parts[3];
      messages.push({ type: 'editImport', chatId, messageId, importId: parts[1], text: previewText(p) });
      messages.push({ type: 'answer', queryId, text: 'Источник: ' + p.source });
    } else if (parts[2] === 'no') {
      delete store.pending[parts[1]];
      messages.push({ type: 'edit', chatId, messageId, text: 'Отменила, ничего не добавлено.' });
      messages.push({ type: 'answer', queryId, text: 'Отменено' });
    } else if (parts[2] === 'go') {
      const c = classify(p);
      const d0 = new Date(p.t); const src = 'список ' + String(d0.getDate()).padStart(2, '0') + '.' + String(d0.getMonth() + 1).padStart(2, '0') + ' ' + parts[1].slice(-4);
      for (const it of c.fresh) {
        const base = it.repair ? { ...it.repair } : { id: newId(), status: 'Идея', project: '', createdAt: nowIso };
        const r = { ...base, year: it.year || '', month: it.month, day: it.day, title: it.title, channel: p.channel, note: it.note || '', sources: src };
        put(r);
      }
      let merged = 0;
      const touched = new Set();
      for (const { hit } of c.dup) {
        if (touched.has(hit.id)) continue;
        touched.add(hit.id);
        const s = srcList(hit);
        let changed = false;
        if (!s.includes(src)) { s.push(src); hit.sources = s.join('; '); merged++; changed = true; }
        const idea = (c.dup.find(x => x.hit === hit).it.note || '').trim();
        if (idea && !String(hit.note || '').includes(idea)) { hit.note = (hit.note ? String(hit.note) + '\n\n' : '') + idea; changed = true; }
        if (changed) put(hit);
      }
      // пустышки (вместо названия — одна дата): не нашли замену — прячем
      let junkHidden = 0;
      const repaired = new Set(c.fresh.filter(it => it.repair).map(it => it.repair.id));
      for (const r of rows) {
        if (isDateOnlyTitle(r.title) && !repaired.has(r.id) && r.status !== 'Отклонён') { r.status = 'Отклонён'; put(r); junkHidden++; }
      }
      delete store.pending[parts[1]];
      messages.push({ type: 'edit', chatId, messageId, text: `✅ Готово · ${chName(p.channel)}\nНовых поводов: ${c.fresh.length}\nСовпадений (стали ×N+1): ${merged}${c.bad.length ? `\nБез даты, пропущено: ${c.bad.length}` : ''}${junkHidden ? `\nПустых строк спрятано: ${junkHidden}` : ''}\n\nКалендарь — кнопка «Календарь» внизу слева.` });
      messages.push({ type: 'answer', queryId, text: 'Добавлено' });
    }
  } else if (parts[0] === 'st') {
    const r = rows.find(x => x.id === parts[1]);
    const st = STATUS[parts[2]];
    if (!r || !st) {
      messages.push({ type: 'answer', queryId, text: 'Не нашла этот повод в таблице' });
    } else {
      r.status = st; put(r);
      messages.push({ type: 'editCard', chatId, messageId, rowId: r.id, text: cardText(r) });
      messages.push({ type: 'answer', queryId, text: 'Статус: ' + st });
    }
  } else {
    messages.push({ type: 'answer', queryId, text: '' });
  }
} else if (tg.message) {
  const msg = tg.message;
  const chatId = msg.chat.id;
  const text = String(msg.text || msg.caption || '').trim();
  const low = text.toLowerCase().replace(/^\//, '');
  const replyTo = msg.reply_to_message ? String(msg.reply_to_message.text || '') : '';
  const idInReply = replyTo.match(/id:([A-Za-z0-9_-]+)/);
  const monM = low.match(/^(январ|феврал|март|апрел|ма[йя]|июн|июл|август|сентябр|октябр|ноябр|декабр)[а-я]*\s*(\d{4})?$/);

  if (idInReply && text) {
    const r = rows.find(x => x.id === idInReply[1]);
    if (!r) messages.push({ type: 'send', chatId, text: 'Не нашла этот повод в таблице.' });
    else {
      r.note = (r.note ? String(r.note) + '\n\n' : '') + text;
      put(r);
      messages.push({ type: 'send', chatId, text: `📝 Добавила в заметки: <b>${esc(r.title)}</b>` });
    }
  } else if (!text || ['start', 'help', 'помощь', 'меню'].includes(low)) {
    messages.push({ type: 'send', chatId, text: HELP });
  } else if (['ближайшие', 'soon', 'скоро'].includes(low)) {
    messages.push({ type: 'send', chatId, text: summary(today, 30, '<b>Ближайшие 30 дней</b>') });
  } else if (['выбранные', 'план'].includes(low)) {
    const end = new Date(today); end.setDate(end.getDate() + 92);
    const list = rows.filter(r => ['Выбран', 'В работе'].includes(r.status)).map(r => [nextDate(r, today), r]).filter(([d]) => d && d <= end).sort((a, b) => a[0] - b[0]);
    messages.push({ type: 'send', chatId, text: list.length ? '<b>Выбранные на 3 месяца</b>\n\n' + list.map(([d, r]) => `<b>${short(d)}</b> ${r.channel === 'tapestry' ? '🟡' : '🔴'} ${esc(r.title)}${MARK[r.status]}`).join('\n') : 'Выбранных поводов на 3 месяца пока нет.' });
  } else if (monM) {
    const mi = MON_KEYS.findIndex(k => k.some(x => monM[1].startsWith(x.slice(0, 3)))) ;
    const mIdx = mi >= 0 ? mi : 0;
    let y = monM[2] ? +monM[2] : today.getFullYear();
    if (!monM[2] && mIdx < today.getMonth()) y++;
    const from = new Date(y, mIdx, 1);
    const days = new Date(y, mIdx + 1, 0).getDate() - 1;
    messages.push({ type: 'send', chatId, text: summary(from, days, `<b>${MON_NOM[mIdx]} ${y}</b>`) + '\n\n⭐ выбран · 🛠 в работе · ✓ вышел. Выбирать — в «Календаре» (кнопка внизу слева).' });
  } else {
    const lines = parseList(text);
    if (!lines.some(l => l.ok)) {
      messages.push({ type: 'send', chatId, text: 'Не нашла в сообщении ни одной даты.\n\n' + HELP });
    } else {
      const importId = Date.now().toString(36).slice(-6) + Math.random().toString(36).slice(2, 4);
      store.pending[importId] = { t: Date.now(), channel: 'pengui', source: '', lines };
      messages.push({ type: 'sendImport', chatId, importId, text: previewText(store.pending[importId]) });
    }
  }
}

return [{ json: { upserts, messages } }];

// все строки листа, каналы (Catalog) и выпуски каналов (только шаг и треки) одним JSON для страницы
// только соседние месяцы (прошлый … +3 вперёд) — страница не тяжелеет с годами
const now = new Date(), base = now.getFullYear() * 12 + now.getMonth();
const ym = (y, m) => { y = Number(y) || 0; m = Number(m) || 0; if (!m) return -1; if (!y) { y = now.getFullYear(); if (y * 12 + m - 1 < base - 2) y++; } return y * 12 + m - 1; };
const near = k => k >= base - 1 && k <= base + 3;
const rows = $('Читаем календарь (страница)').all().map(i => i.json).filter(r => r && String(r.id || '').trim()).filter(r => {
  const rel = String(r.release || '').match(/^(\d{4})-(\d{2})/);
  return near(ym(r.year, r.month)) || (rel && near(ym(rel[1], rel[2])));
});
const channels = $('Читаем каталог (страница)').all().map(i => i.json).filter(c => c && String(c.Channel || '').trim());
let raw = [];
try { raw = $('Читаем выпуски (страница)').all().map(i => i.json); } catch (e) {}
const projects = raw.filter(p => p && /^\d{8}_\d{6}_[a-z0-9]+$/i.test(String(p.sys_ProjectID || '').trim())).map(p => {
  const id = String(p.sys_ProjectID).trim();
  return { id, ch: id.split('_').slice(2).join('_').toLowerCase(), status: String(p.sys_Status || '').trim(),
    tracks: !!String(p.sys_AudioZipUrl || '').trim(), title: String(p.ai_Title || '').slice(0, 160) };
});
return [{ json: { body: JSON.stringify({ rows, channels, projects }) } }];

// строка, которую прислала страница: берём только известные колонки
const COLS = ["id", "year", "month", "day", "title", "channel", "status", "project", "note", "sources", "createdAt", "updatedAt", "title_ru", "release", "step", "posted", "tag"];
const STATUSES = ['Идея','Выбран','В работе','Вышел','Отклонён'];
const r = ($('Сохранение со страницы').first().json.body || {}).row || {};
const id = String(r.id || '').trim();
if (!/^[A-Za-z0-9_-]{2,40}$/.test(id)) throw new Error('bad id');
const m = Number(r.month), d = Number(r.day);
if (!(m >= 1 && m <= 12 && d >= 1 && d <= 31)) throw new Error('bad date');
const now = new Date().toISOString();
const out = {};
for (const c of COLS) out[c] = r[c] === null || r[c] === undefined ? '' : String(r[c]).slice(0, 20000);
out.id = id; out.month = String(m); out.day = String(d);
if (!STATUSES.includes(out.status)) out.status = 'Идея';
if (out.release && !/^\d{4}-\d{2}-\d{2}$/.test(out.release)) out.release = '';
if (out.step && !/^[0-5]$/.test(out.step)) out.step = '';
if (out.posted !== 'да') out.posted = '';
if (out.project && !/^\d{8}_\d{6}_[a-z0-9]+$/i.test(out.project)) out.project = '';
out.channel = out.channel.toLowerCase();   // пусто — повод общий, для любого канала
out.updatedAt = now;
if (!out.createdAt) out.createdAt = now;
return [{ json: out }];

// Автосбор: какой месяц и что искать. Месяц — из команды («собери ноябрь»), иначе следующий.
// Что искать для каждого канала — лист «Автосбор» (Канал | Что искать | Модель): здесь только механика.
const MON = [['янв','jan'],['фев','feb'],['мар','mar'],['апр','apr'],['мая','май','may'],['июн','jun'],['июл','jul'],['авг','aug'],['сен','sep'],['окт','oct'],['ноя','nov'],['дек','dec']];
const MON_EN = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const MON_RU = ['январь','февраль','март','апрель','май','июнь','июль','август','сентябрь','октябрь','ноябрь','декабрь'];
let msg = null;
try { msg = $('Telegram Trigger').first().json.message || null; } catch (e) {}
const text = String((msg && msg.text) || '').toLowerCase();
const now = new Date();
let y = now.getFullYear(), m = now.getMonth() + 2;            // следующий месяц, 1..13
const w = (text.match(/собер\S*\s+(\S+)/) || [])[1] || '';
const mi = MON.findIndex(ks => ks.some(k => w.startsWith(k)));
if (mi >= 0) { m = mi + 1; if (m < now.getMonth() + 1) y++; }
if (m > 12) { m -= 12; y++; }
const srows = $('Читаем, что искать').all().map(i => i.json || {});
// что искать — общий текст листа «Автосбор» (без каналов); страны — для официальных праздников
const what = srows.map(r => String(r['Что искать'] || '').trim()).filter(Boolean).join('\n');
const model = srows.map(r => String(r['Модель'] || '').trim()).find(Boolean) || 'gpt-5';
const countries = [...new Set((srows.map(r => String(r['Страны'] || '')).join(',').toUpperCase().match(/\b[A-Z]{2}\b/g) || []))];
const chatId = msg ? msg.chat.id : 285577543;
if (!what) return [{ json: { need: false, chatId, text: 'Лист «Автосбор» пуст: не знаю, что искать.' } }];
const last = new Date(y, m, 0).getDate();
const ranges = [[1, 10], [11, 20], [21, last]];   // три запроса по ~10 дней — ответы не гигантские
return [{ json: { need: true, chatId, y, m, monthRu: MON_RU[m - 1], monthEn: MON_EN[m - 1], what, model, countries, ranges,
  text: '🔎 Ищу поводы на ' + MON_RU[m - 1] + ' ' + y + ' — три части по десять дней, это 5–15 минут.' } }];

// Ответы ИИ (три части месяца) → строки листа «Календарь». Повторы (тот же день и то же название) с листом
// и между частями не добавляются. Новые — «Идея», без канала, суть — в note, значок — в tag.
const z = $('Автосбор: задание').first().json;
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const parts = $('OpenAI: ищем поводы').all().map(i => i.json || {});
let items = []; const bad = [];
parts.forEach((resp, n) => {
  const out = (resp.output || []).filter(i => i.type === 'message')
    .flatMap(i => (i.content || []).filter(c => c.type === 'output_text').map(c => c.text)).join('\n');
  try {
    const a = out.indexOf('{'), b = out.lastIndexOf('}');
    const arr = JSON.parse(out.slice(a, b + 1)).items;
    if (!Array.isArray(arr)) throw new Error('no items');
    items = items.concat(arr);
  } catch (e) {
    bad.push('часть ' + (n + 1) + ': ' + (resp.error ? String(resp.error.message || JSON.stringify(resp.error)).slice(0, 150) : 'ответ не разобрался'));
  }
});
if (!items.length) return [{ json: { rows: [], text: '⚠️ Автосбор на ' + z.monthRu + ' не получился: ' + esc(bad.join('; ') || 'пусто') } }];
const norm = s => String(s || '').toLowerCase().replace(/[^a-zа-яё0-9]+/gi, ' ').trim();
const seen = new Set();
for (const r of $('Читаем календарь (автосбор)').all().map(i => i.json)) {
  if (!r || !r.id) continue;
  seen.add(Number(r.month) + '-' + Number(r.day) + '|' + norm(r.title));
}
const now = new Date().toISOString();
const stamp = now.slice(8, 10) + '.' + now.slice(5, 7);
const rows = []; let found = 0;
for (const it of items) {
  const md = String(it.date || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!md || Number(md[1]) !== z.y || Number(md[2]) !== z.m) continue;
  const title = String(it.title || '').trim();
  if (!title) continue;
  found++;
  const k = z.m + '-' + Number(md[3]) + '|' + norm(title);
  if (seen.has(k)) continue;
  seen.add(k);
  rows.push({ id: 'a' + Date.now().toString(36) + rows.length.toString(36) + Math.random().toString(36).slice(2, 5),
    year: String(z.y), month: String(z.m), day: String(Number(md[3])), title, channel: '',
    status: 'Идея', project: '', note: String(it.about_ru || '').trim().slice(0, 1200),
    sources: 'автосбор ' + stamp + (it.source ? '; ' + String(it.source).trim() : ''),
    createdAt: now, updatedAt: now, title_ru: String(it.title_ru || '').trim(), tag: String(it.tag || '').trim().slice(0, 8) });
}
rows.sort((a, b) => Number(a.day) - Number(b.day));
let text = '🗓 Автосбор на ' + z.monthRu + ' ' + z.y + ': найдено ' + found + ', новых ' + rows.length + '. Всё — в календаре, у каждого повода суть.';
if (bad.length) text += '\n⚠️ Не получилось: ' + esc(bad.join('; ')) + '. Можно повторить: «собери ' + z.monthRu + '».';
return [{ json: { rows, text } }];

// по элементу на страну — официальные праздники из бесплатного календаря (date.nager.at)
const z = $('Автосбор: задание').first().json;
const list = (z.countries && z.countries.length) ? z.countries : ['US'];
return list.map(cc => ({ json: { cc, y: z.y } }));

// три запроса к ИИ (дни 1–10, 11–20, 21–конец); в каждый — официальные праздники стран этих дней
const z = $('Автосбор: задание').first().json;
const pad = n => String(n).padStart(2, '0');
const pref = z.y + '-' + pad(z.m) + '-';
const hol = {};
for (const it of $input.all()) {
  const h = it.json || {};
  const d = String(h.date || '');
  const name = String(h.name || h.localName || '').trim();
  if (!d.startsWith(pref) || !name) continue;
  const key = d + '|' + name.toLowerCase();
  (hol[key] = hol[key] || { date: d, name, local: String(h.localName || '').trim(), cc: [] }).cc.push(String(h.countryCode || ''));
}
const hl = Object.values(hol);
const FORMAT = 'Answer with JSON only, no other text: {"items": [{"date": "YYYY-MM-DD", "title": "the original name as it is known (English if it has one)", '
  + '"title_ru": "Russian name", "about_ru": "2-3 sentences in Russian: what this day is, where it comes from, how it is marked", '
  + '"tag": "one emoji: the country flag for a national or local occasion, 🌍 for international or world days, 🕯 for religious, 🌙 for seasonal or astronomical, 🎗 for memorial", '
  + '"source": "site name"}]}. Never invent a date; skip what you cannot date for ' + z.y + '. Do not assign channels and do not suggest episode ideas.';
return z.ranges.map(([a, b]) => {
  const inR = hl.filter(h => { const d = Number(h.date.slice(8, 10)); return d >= a && d <= b; });
  const off = inR.length ? '\n\nOfficial public holidays in this period (include every one, each as its own item; name the countries in about_ru):\n'
    + inR.map(h => '- ' + h.date + ' ' + h.name + (h.local && h.local !== h.name ? ' (' + h.local + ')' : '') + ' — ' + [...new Set(h.cc)].join(', ')).join('\n') : '';
  const instructions = 'You collect occasions for a content calendar. Period: ' + z.monthEn + ' ' + a + '-' + b + ', ' + z.y
    + '. Use web search to check the dates for this year.\nWhat to collect:\n' + z.what + off + '\n\n' + FORMAT + ' Up to 120 items, sorted by date.';
  const requestBody = { model: z.model, instructions, tools: [{ type: 'web_search' }],
    input: [{ role: 'user', content: 'Collect the occasions for ' + z.monthEn + ' ' + a + '-' + b + ', ' + z.y + ' as JSON.' }] };
  if (/^(gpt-5|o\d)/.test(z.model)) requestBody.reasoning = { effort: 'low' };
  return { json: { a, b, requestBody } };
});
